import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        byte[] s = next().getBytes();
        int n = s.length;
        // valid[i]: the prefix of length i has no two equal adjacent characters.
        boolean[] valid = new boolean[n + 1];
        valid[0] = valid[1] = true;
        for (int i = 1; i < n; i++) valid[i + 1] = valid[i] && s[i] != s[i - 1];
        // The rightmost possible first change gives the smallest result.
        for (int i = n - 1; i >= 0; i--) {
            if (!valid[i]) continue;
            for (int c = s[i] + 1; c <= 'z'; c++) {
                if (i > 0 && c == s[i - 1]) continue;
                byte[] out = Arrays.copyOf(s, n + 1);
                out[i] = (byte) c;
                for (int j = i + 1; j < n; j++) out[j] = (byte) (out[j - 1] != 'a' ? 'a' : 'b');
                out[n] = '\n';
                System.out.write(out, 0, n + 1);
                System.out.flush();
                return;
            }
        }
        System.out.println("-1");
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextToken() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := nextToken()
	n := len(s)
	// valid[i]: the prefix of length i has no two equal adjacent characters.
	valid := make([]bool, n+1)
	valid[0], valid[1] = true, true
	for i := 1; i < n; i++ {
		valid[i+1] = valid[i] && s[i] != s[i-1]
	}
	// The rightmost possible first change gives the smallest result.
	for i := n - 1; i >= 0; i-- {
		if !valid[i] {
			continue
		}
		for c := s[i] + 1; c <= 'z'; c++ {
			if i > 0 && c == s[i-1] {
				continue
			}
			out := make([]byte, n+1)
			copy(out, s[:i])
			out[i] = c
			for j := i + 1; j < n; j++ {
				if out[j-1] != 'a' {
					out[j] = 'a'
				} else {
					out[j] = 'b'
				}
			}
			out[n] = '\n'
			os.Stdout.Write(out)
			return
		}
	}
	fmt.Println("-1")
}
